<script>
"use strict";

/* Fallback copy of the CSV, used if fetching fails (e.g. page opened via file://). */
const EMBEDDED_CSV = [
  "district,year,children_due,children_fully_immunised,source",
  "Gaya,2022,1000,780,synthetic smoke fixture",
  "Nalanda,2022,800,680,synthetic smoke fixture",
  "Purnia,2022,900,630,synthetic smoke fixture",
  "Gaya,2023,1100,935,synthetic smoke fixture",
  "Nalanda,2023,850,765,synthetic smoke fixture",
  "Purnia,2023,1000,760,synthetic smoke fixture"
].join("\n");

const CSV_URL = "district_immunisation.csv";

function parseCSV(text) {
  const rows = [];
  let row = [], field = "", inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') {
        if (text[i + 1] === '"') { field += '"'; i++; }
        else { inQuotes = false; }
      } else { field += c; }
    } else if (c === '"') {
      inQuotes = true;
    } else if (c === ",") {
      row.push(field); field = "";
    } else if (c === "\n" || c === "\r") {
      if (c === "\r" && text[i + 1] === "\n") i++;
      row.push(field); field = "";
      if (row.some(f => f.trim() !== "")) rows.push(row);
      row = [];
    } else {
      field += c;
    }
  }
  row.push(field);
  if (row.some(f => f.trim() !== "")) rows.push(row);
  return rows;
}

function rowsToRecords(rows) {
  const header = rows[0].map(h => h.trim());
  const idx = name => header.indexOf(name);
  const iD = idx("district"), iY = idx("year"), iDue = idx("children_due"),
        iF = idx("children_fully_immunised"), iS = idx("source");
  if ([iD, iY, iDue, iF].some(n => n === -1)) {
    throw new Error("CSV is missing required columns (district, year, children_due, children_fully_immunised)");
  }
  const records = [];
  for (let r = 1; r < rows.length; r++) {
    const rec = {
      district: rows[r][iD].trim(),
      year: parseInt(rows[r][iY], 10),
      due: parseInt(rows[r][iDue], 10),
      immunised: parseInt(rows[r][iF], 10),
      source: iS !== -1 && rows[r][iS] ? rows[r][iS].trim() : "unspecified"
    };
    if (!rec.district || Number.isNaN(rec.year) || Number.isNaN(rec.due) || Number.isNaN(rec.immunised)) continue;
    records.push(rec);
  }
  return records;
}

function coverage(rec) {
  return rec.due > 0 ? (rec.immunised / rec.due) * 100 : 0;
}

function fmt(n) { return n.toLocaleString("en-US"); }

function rateClass(pct) {
  if (pct >= 80) return "rate-good";
  if (pct >= 60) return "rate-mid";
  return "rate-low";
}

function barClass(pct) {
  if (pct >= 80) return "";
  if (pct >= 60) return "mid";
  return "low";
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, ch => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;"
  }[ch]));
}

let DATA = [];
let selectedYear = null;

function uniqueSorted(values, num) {
  const set = [...new Set(values)];
  return set.sort((a, b) => (num ? a - b : String(a).localeCompare(String(b))));
}
