function renderYearControl(years) {
  const sel = document.getElementById("year-select");
  sel.innerHTML = years.map(y =>
    '<option value="' + y + '">' + y + '</option>'
  ).join("");
  sel.value = String(years[years.length - 1]);
  sel.addEventListener("change", () => { selectedYear = parseInt(sel.value, 10); render(); });
  selectedYear = parseInt(sel.value, 10);
}

function render() {
  const year = selectedYear;
  const recs = DATA.filter(r => r.year === year);
  const districts = uniqueSorted(recs.map(r => r.district), false);
  const years = uniqueSorted(DATA.map(r => r.year), true);

  document.getElementById("bars-title").textContent = "District comparison \u2014 " + year;
  document.getElementById("table-title").textContent = "Details \u2014 " + year;

  /* Bars, best coverage first */
  const sorted = [...recs].sort((a, b) => coverage(b) - coverage(a));
  document.getElementById("bars").innerHTML = sorted.map(r => {
    const pct = coverage(r);
    return '<div class="row">' +
      '<div class="row-head">' +
        '<span>' + escapeHtml(r.district) + '</span>' +
        '<span class="pct">' + pct.toFixed(1) + '% ' +
          '<span class="count">' + fmt(r.immunised) + ' / ' + fmt(r.due) + '</span>' +
        '</span>' +
      '</div>' +
      '<div class="bar-track" role="img" aria-label="' + escapeHtml(r.district) + ': ' + pct.toFixed(1) + ' percent">' +
        '<div class="bar-fill ' + barClass(pct) + '" style="width:' + Math.min(pct, 100).toFixed(1) + '%"></div>' +
      '</div>' +
    '</div>';
  }).join("");

  /* Detail table */
  document.querySelector("#detail-table tbody").innerHTML = sorted.map(r => {
    const pct = coverage(r);
    return '<tr>' +
      '<td>' + escapeHtml(r.district) + '</td>' +
      '<td class="num">' + fmt(r.due) + '</td>' +
      '<td class="num">' + fmt(r.immunised) + '</td>' +
      '<td class="num ' + rateClass(pct) + '">' + pct.toFixed(1) + '%</td>' +
    '</tr>';
  }).join("");

  /* District x year grid */
  const gridHead = '<tr><th>District</th>' +
    years.map(y => '<th class="num">' + y + '</th>').join("") + '</tr>';
  document.querySelector("#grid-table thead").innerHTML = gridHead;
  document.querySelector("#grid-table tbody").innerHTML = districts.map(d => {
    const cells = years.map(y => {
      const rec = DATA.find(r => r.district === d && r.year === y);
      if (!rec) return '<td class="num">\u2014</td>';
      const pct = coverage(rec);
      return '<td class="num ' + rateClass(pct) + '" title="' + fmt(rec.immunised) + ' of ' + fmt(rec.due) + '">' + pct.toFixed(1) + '%</td>';
    }).join("");
    return '<tr><td>' + escapeHtml(d) + '</td>' + cells + '</tr>';
  }).join("");
}

function renderSources(sources) {
  const list = sources.map(escapeHtml).join("; ");
  document.getElementById("source-badge").innerHTML = "Source: " + list;
  document.getElementById("footer").innerHTML =
    'Data file: <a href="' + CSV_URL + '">' + CSV_URL + '</a> &middot; Source(s): ' + list + ' &middot; ' + DATA.length + ' records';
}

async function loadData() {
  let usedFallback = false;
  try {
    const res = await fetch(CSV_URL);
    if (!res.ok) throw new Error("HTTP " + res.status);
    const text = await res.text();
    DATA = rowsToRecords(parseCSV(text));
  } catch (err) {
    usedFallback = true;
    DATA = rowsToRecords(parseCSV(EMBEDDED_CSV));
  }
  if (!DATA.length) {
    document.getElementById("content").innerHTML =
      '<div class="error">Could not read any immunisation records from the data file.</div>';
    return;
  }
  const years = uniqueSorted(DATA.map(r => r.year), true);
  renderYearControl(years);
  render();
  renderSources(uniqueSorted(DATA.map(r => r.source), false));
  if (usedFallback) {
    const notes = document.querySelectorAll(".note");
    if (notes.length) notes[0].textContent += " (Showing embedded copy of " + CSV_URL + " \u2014 file could not be fetched.)";
  }
}

loadData();
</script>
</body>
</html>
